import React from "react";
import { Box } from "@mui/material";

const isEmojiIcon = (icon) =>
  typeof icon === "string" && /\p{Extended_Pictographic}/u.test(icon.trim());

const normalizeIconName = (icon) =>
  String(icon || "food")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9-]/g, "");

const IngredientIcon = ({ icon = "food", sx = {} }) => {
  const value = String(icon || "food").trim();
  if (!value) return null;

  if (isEmojiIcon(value)) {
    return (
      <Box component="span" sx={{ fontSize: "1.1rem", lineHeight: 1, ...sx }}>
        {value}
      </Box>
    );
  }

  const iconClass = normalizeIconName(value);
  if (!iconClass) return null;

  return (
    <Box
      component="span"
      className={`mdi mdi-${iconClass}`}
      sx={{
        fontSize: 20,
        color: "#4CC66E",
        lineHeight: 1,
        flexShrink: 0,
        ...sx,
      }}
      aria-hidden
    />
  );
};

export default IngredientIcon;
