import { apiGetJson, BASE_URL } from '../../utils/apiClient';

export const flattenWeekMeals = (weekData) => {
  const days = Array.isArray(weekData?.days)
    ? weekData.days
    : Array.isArray(weekData)
      ? weekData
      : [];

  const normalizeMealListItem = (item) => {
    if (!item || typeof item !== 'object') return item;
    const macros = item.macros || item.energy || {};
    return {
      ...item,
      title: item.title ?? item.recipe_name ?? item.name,
      name: item.name ?? item.recipe_name ?? item.title,
      category: item.category ?? item.slot_type,
      calories: item.calories ?? macros.calories_kcal ?? macros.calories,
      protein: item.protein ?? macros.protein_g ?? macros.protein,
      carbs: item.carbs ?? macros.carbs_g ?? macros.carbs,
      fats: item.fats ?? macros.fats_g ?? macros.fats,
      preparation_time:
        item.preparation_time ?? item.prep_time_min ?? item.prep_time,
    };
  };

  return days.flatMap((day) => {
    const dayMeals = Array.isArray(day?.meals) ? day.meals : [];
    return dayMeals.map((meal) =>
      normalizeMealListItem({
        ...meal,
        day_of_week: meal.day_of_week ?? day.day_of_week,
      }),
    );
  });
};

export const normalizeWorkoutPlans = (rawWorkouts) =>
  rawWorkouts.map((w) => {
    const dateObj = w.workout_date ? new Date(w.workout_date) : null;
    const dayName = dateObj
      ? dateObj.toLocaleDateString(undefined, { weekday: 'long' })
      : '';
    const status = w.is_completed
      ? 'completed'
      : w.is_skipped
        ? 'skipped'
        : 'pending';
    const exercises = Array.isArray(w.exercises) ? w.exercises : [];
    return {
      ...w,
      id: w.workout_id,
      name: dayName ? `${dayName} Workout` : 'Workout Plan',
      workout_type: (w.source || 'ai').replace(/_/g, ' '),
      status,
      plan_date: w.workout_date,
      duration_minutes:
        w.total_estimated_duration_minutes ?? w.total_minutes ?? 0,
      estimated_calories: w.burn_target_kcal ?? w.total_calories_target ?? 0,
      exercises_count: w.exercises_count ?? exercises.length,
      sets_count: w.total_sets ?? 0,
      exercises,
    };
  });

export const fetchUserDetails = async (userId, token) => {
  const result = await apiGetJson(`/users/${userId}/details`, token);
  return result.data;
};

export const fetchUserMeasurements = async (userId, token) => {
  const result = await apiGetJson(`/users/${userId}/measurements`, token, {
    limit: 100,
  });
  const history = Array.isArray(result.data?.history)
    ? result.data.history
    : Array.isArray(result.data)
      ? result.data
      : [];
  return {
    history,
    graph: result.data?.graph || null,
  };
};

export const fetchUserReminders = async (userId, token) => {
  const result = await apiGetJson(`/users/${userId}/reminders`, token);
  const list = Array.isArray(result.data?.reminders)
    ? result.data.reminders
    : Array.isArray(result.data)
      ? result.data
      : [];
  return {
    reminders: list,
    doNotDisturb: Boolean(result.data?.do_not_disturb_enabled),
  };
};

export const fetchUserMealsWeek = async (userId, token, week) => {
  const result = await apiGetJson(`/v2/meal/week/${week}`, token, {
    user_id: userId,
  });
  return flattenWeekMeals(result.data);
};

export const fetchUserWorkouts = async (userId, token, { page, limit, q }) => {
  const params = {
    user_id: userId,
    sort_by: 'created_at',
    sort_order: 'desc',
    page,
    limit,
  };
  if (q) params.q = q;

  const result = await apiGetJson(
    `/workouts/v2/admin/by-user/${userId}`,
    token,
    params,
  );

  const rawWorkouts = Array.isArray(result.data?.workouts)
    ? result.data.workouts
    : Array.isArray(result.data)
      ? result.data
      : [];

  return {
    workouts: normalizeWorkoutPlans(rawWorkouts),
    total: result.data?.pagination?.total ?? rawWorkouts.length,
  };
};

export const fetchUserActivityLogs = async (userId, token, { page, limit }) => {
  const result = await apiGetJson(`/users/${userId}/activity-logs`, token, {
    page,
    limit,
  });

  const activities = Array.isArray(result.data?.activities)
    ? result.data.activities
    : Array.isArray(result.data)
      ? result.data
      : [];

  return {
    activities,
    total: result.data?.pagination?.totalRecords || activities.length || 0,
  };
};

export const fetchUserMiniGoals = async (userId, token) => {
  const result = await apiGetJson(`/mini-goals/user/${userId}`, token);
  return Array.isArray(result.data) ? result.data : [];
};

export const fetchUserGoals = async (userId, token) => {
  const result = await apiGetJson(`/goals/user/${userId}`, token);
  const goals = Array.isArray(result.data)
    ? result.data
    : Array.isArray(result.data?.goals)
      ? result.data.goals
      : result.data?.goal
        ? [result.data.goal]
        : result.data
          ? [result.data]
          : [];
  return goals;
};

export const fetchMealDetailsById = async (userId, token, mealId) => {
  const response = await fetch(
    `${BASE_URL}/v2/meal/meals/${mealId}?user_id=${encodeURIComponent(userId)}`,
    {
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`,
      },
    },
  );
  const result = await response.json();
  if (!response.ok || result.error) {
    throw new Error(result.message || 'Failed to fetch meal details');
  }
  return result.data?.meal ?? result.data;
};
