export const useUserGoalsQuery = (userId, token, enabled) =>
  useQuery({
    queryKey: queryKeys.userDetails.goals(userId),
    queryFn: () => fetchUserGoals(userId, token),
    enabled: Boolean(userId && token && enabled),
  });
