const REGION_DISPLAY = (() => {
  try {
    return new Intl.DisplayNames(["en"], { type: "region" });
  } catch (_) {
    return null;
  }
})();

const titleCaseToken = (token) =>
  token
    .replace(/_/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/\b\w/g, (c) => c.toUpperCase());

const humanizeOnboardingAnswer = (question, answer) => {
  if (answer === null || answer === undefined) return "-";
  const raw = String(answer).trim();
  if (!raw) return "-";

  const q = String(question || "").toLowerCase();

  // Country: resolve ISO 3166 alpha-2 codes (e.g. "AU" -> "Australia").
  if (q.includes("country") && /^[A-Za-z]{2}$/.test(raw)) {
    const region = REGION_DISPLAY?.of(raw.toUpperCase());
    if (region && region.toUpperCase() !== raw.toUpperCase()) return region;
  }

  // Multi-value answers (e.g. "adjustable_db, resistance_bands").
  const parts = raw
    .split(",")
    .map((p) => p.trim())
    .filter(Boolean);

  if (parts.length > 1) {
    return parts
      .map((p) => ONBOARDING_ANSWER_LABELS[p.toLowerCase()] || titleCaseToken(p))
      .join(", ");
  }

  const key = raw.toLowerCase();
  if (ONBOARDING_ANSWER_LABELS[key]) return ONBOARDING_ANSWER_LABELS[key];

  // Leave values that already contain digits/units (e.g. "25 kg", "0.25") as-is.
  if (/\d/.test(raw)) return raw;

  // Only prettify snake_case / lowercase codes; preserve free-text answers.
  if (/^[a-z0-9_]+$/.test(raw)) return titleCaseToken(raw);

  return raw;
};

