  const [isGoalsExporting, setIsGoalsExporting] = useState(false);
  const [isMealsExporting, setIsMealsExporting] = useState(false);
  const [isWorkoutsExporting, setIsWorkoutsExporting] = useState(false);
  const [isActivityLogsExporting, setIsActivityLogsExporting] = useState(false);
  const [openResetPasswordModal, setOpenResetPasswordModal] = useState(false);
  const [isResettingPassword, setIsResettingPassword] = useState(false);

