      const items = extractExportList(result, 'goals');
      const filename = `User_Goals_${user?.name?.replace(/\s+/g, '_') || id}_${dates.startDate.format('YYYYMMDD')}_to_${dates.endDate.format('YYYYMMDD')}`;

