import React from "react";
import { Chip } from "@mui/material";

/**
 * Read-only chip for labels/tags. Sets clickable={false} so MUI v7 does not
 * attach a root onClick handler that throws when the chip is pressed.
 */
const DisplayChip = ({ onClick: _onClick, clickable: _clickable, ...props }) => (
  <Chip clickable={false} onClick={() => {}} {...props} />
);

export default DisplayChip;
