const KNOWN_STATUSES = {
  active: { label: 'Active', color: '#4CC66E' },
  trialing: { label: 'Trial', color: '#5AC8FA' },
  trial: { label: 'Trial', color: '#5AC8FA' },
  cancelled: { label: 'Cancelled', color: '#FF5050' },
  canceled: { label: 'Cancelled', color: '#FF5050' },
  expired: { label: 'Expired', color: '#FF5050' },
  past_due: { label: 'Past Due', color: '#FFC107' },
  inactive: { label: 'Inactive', color: '#8B8D97' },
  free: { label: 'Free', color: '#8B8D97' },
};

const isFutureDate = (dateString) => {
  if (!dateString) return false;
  return new Date(dateString).getTime() > Date.now();
};

export const resolveSubscriptionStatus = ({ user, profile, subscription } = {}) => {
  const rawStatus = subscription?.status?.toLowerCase?.().trim();

  if (rawStatus && rawStatus !== 'unknown' && KNOWN_STATUSES[rawStatus]) {
    return KNOWN_STATUSES[rawStatus];
  }

  if (user?.is_lifetime_free) {
    return { label: 'Lifetime Free', color: '#9F6EDA' };
  }

  if (profile?.is_iap_trail_active) {
    return { label: 'Trial', color: '#5AC8FA' };
  }

  if (profile?.is_iap_active || isFutureDate(profile?.iap_end_date)) {
    return { label: 'Active', color: '#4CC66E' };
  }

  if (profile?.is_free_plan_active || isFutureDate(profile?.free_plan_end_date)) {
    return { label: 'Free Plan', color: '#5AC8FA' };
  }

  if (subscription?.has_subscription && subscription?.plan_key) {
    return { label: 'Active', color: '#4CC66E' };
  }

  return { label: 'Free', color: '#8B8D97' };
};
